function passage(score,entry){const duration=beats=>{const seconds=Math.round(beats*60/C.clamp(Math.round(score.tempo),45,180));return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')};dialog('Make this score your own','<p>'+esc(entry.title)+' · '+esc(entry.composer||'Your score')+'</p><p>Full score: '+duration(score.beats)+' at the import pace · '+Math.ceil(score.beats)+' quarter beats</p><label>Import<select id="scoreExtent"><option value="full">Full MIDI · all notes</option><option value="passage">Choose a shorter passage</option></select></label><div id="scorePassage" hidden><label>Start at quarter beat<input id="scoreStart" type="number" min="0" max="'+Math.floor(score.beats)+'" value="0"></label><label>Passage length · quarter beats<input id="scoreBeats" type="number" min="4" max="'+Math.ceil(score.beats)+'" value="32"></label></div><label>Playback pace · BPM<input id="scoreTempo" type="number" min="45" max="180" value="'+C.clamp(Math.round(score.tempo),45,180)+'"></label><p id="scoreDuration" class="hint"></p><label>Sound<select id="scoreInstrument">'+['piano','felt','chip','crunch','musicbox','harp','strings','lofi'].map(k=>'<option value="'+k+'">'+C.voices[k].name+'</option>').join('')+'</select></label><p class="hint">'+esc(entry.rights||'Your original source rights apply.')+' Notes remain editable. Import uses a fixed playback pace; source tempo changes are not reproduced. Editable sessions currently support up to three minutes and 96 bars.</p><button id="scoreLoad" class="primary">Open full MIDI</button>');const update=()=>{const full=$('scoreExtent').value==='full',beats=full?score.beats:+$('scoreBeats').value,seconds=Math.round(beats*60/(+$('scoreTempo').value||120));$('scorePassage').hidden=full;$('scoreLoad').textContent=full?'Open full MIDI':'Open editable passage';$('scoreDuration').textContent='Import length: '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')};for(const key of ['scoreExtent','scoreBeats','scoreTempo'])$(key).oninput=update;update();$('scoreLoad').onclick=()=>{try{install(build(score,{name:entry.title,start:+$('scoreStart').value,beats:+$('scoreBeats').value,full:$('scoreExtent').value==='full',tempo:+$('scoreTempo').value,instrument:$('scoreInstrument').value,rights:(entry.rights||'User-supplied MIDI')+(entry.url?'\nSource: '+entry.url:'')}))}catch(e){status(e.message)}};}

function open(){dialog('Scores to explore','<p>Recognisable music, made from editable notes. Try a piano study, then hear the same passage as crunchy pixels or soft glass-like bells.</p><div class="score-cards">'+catalog.map(e=>'<article class="score-card"><h3>'+esc(e.title)+'</h3><p>'+esc(e.composer)+'</p><p class="hint">'+esc(e.style)+'</p><button data-score="'+e.id+'">Choose passage & sound…</button></article>').join('')+'</div><button id="scoreImport" style="margin-top:16px">Import your MIDI score…</button><p class="hint">Opening a score replaces this arrangement, with undo. Each score shows its source rights. The Vivaldi edition is CC BY-SA; the three piano editions are public domain. Jago synthesises the audio locally.</p>');document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>{const e=catalog.find(x=>x.id===b.dataset.score);const score=e.project?{notes:C.events(e.project).map(n=>({track:e.project.tracks.findIndex(t=>t.id===n.track),channel:0,start:n.time*e.project.tempo/60,end:(n.time+n.duration)*e.project.tempo/60,pitch:n.pitch,velocity:n.velocity})),parts:e.project.tracks.map((t,i)=>({track:i,name:t.name})),tempo:e.project.tempo,beats:C.totalBars(e.project)*4}:parse(Uint8Array.from(atob(e.midi),c=>c.charCodeAt(0)));passage(score,e)});$('scoreImport').onclick=()=>{const f=document.createElement('input');f.type='file';f.accept='.mid,.midi';f.onchange=async()=>{try{const file=f.files[0];if(file)passage(parse(await file.arrayBuffer()),{title:file.name})}catch(e){status(e.message)}};f.click()};}
